#include <iostream>
#include <sstream>
#include <iomanip>
#include <vector>
#include <string>

struct Student {
    std::string name;
    int age;
    double score;
};

int main() {
    // Simulate formatted stream reading without disk dependencies
    std::string simulatedInput = "2\nAlice Johnson\n20 8.5\nBob Smith\n19 9.25\n";
    std::istringstream inStream(simulatedInput);

    int count = 0;
    if (!(inStream >> count)) {
        std::cerr << "Read error: unable to get record count.\n";
        return 1;
    }

    std::vector<Student> students;
    std::string dummy;
    std::getline(inStream, dummy); // Consume newline

    for (int i = 0; i < count; ++i) {
        Student s;
        if (std::getline(inStream, s.name) && (inStream >> s.age >> s.score)) {
            students.push_back(s);
            std::getline(inStream, dummy); // Consume trailing newline
        }
    }

    // Format and print table output
    std::ostringstream outStream;
    outStream << students.size() << "\n";
    for (const auto& s : students) {
        outStream << std::left << std::setw(16) << s.name
                  << std::right << std::setw(4) << s.age
                  << std::fixed << std::setprecision(1) << std::setw(8) << s.score
                  << "\n";
    }

    std::cout << outStream.str();
    std::cout << "Stream good: " << std::boolalpha << outStream.good() << std::endl;
    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    // Use std::stringstream to model bidirectional seek and tell deterministically
    std::stringstream stream("Hello, World!");

    // 1. Query stream size using seekg and tellg
    stream.seekg(0, std::ios::end);
    std::streampos size = stream.tellg();
    std::cout << "Stream size: " << size << " bytes\n";

    // 2. Reposition read pointer to beginning
    stream.seekg(0, std::ios::beg);
    std::string word;
    stream >> word;
    std::cout << "First word: " << word << "\n";
    std::cout << "Current tellg: " << stream.tellg() << "\n";

    // 3. Move put pointer and overwrite content
    stream.seekp(7, std::ios::beg);
    stream.write("C++17", 5);

    // 4. Print modified stream content
    std::cout << "Modified content: " << stream.str() << "\n";
    return 0;
}
